"""Create a local, offline sensor-timeline viewer from actual verified replay panels."""
import hashlib,json
from pathlib import Path
root=Path(__file__).resolve().parents[1];parts=[('tum-static-final',None),('tum-xyz-final',None),('fixture-final',170),('jaad-final',None)];playlist=[];segments=[];offset=0.
for name,limit in parts:
    directory=root/'demo'/name;rows=[json.loads(s) for s in (directory/'messages.jsonl').read_text().splitlines()]
    if limit:rows=rows[:limit]
    start=rows[0]['timestamp_ns'];duration=(rows[-1]['timestamp_ns']-start)/1e9
    panels=[]
    for panel in sorted(directory.glob('panel-*.png')):
        index=int(panel.stem.split('-')[-1])
        if index>=len(rows):continue
        entry={'time_s':offset+(rows[index]['timestamp_ns']-start)/1e9,'file':str(panel.relative_to(root/'demo')),'segment':name,'sample_id':rows[index]['sample_id'],'sha256':hashlib.sha256(panel.read_bytes()).hexdigest()};playlist.append(entry);panels.append(entry['file'])
    provenance=json.loads((directory/'run.json').read_text())
    segments.append({'name':name,'run_id':provenance['run_id'],'run_metadata_file':str((directory/'run.json').relative_to(root/'demo')),'start_s':offset,'duration_s':duration,'sensor_frames':len(rows),'panels':panels,'messages_sha256':hashlib.sha256((directory/'messages.jsonl').read_bytes()).hexdigest(),'limit_note':'first170 of700actually processed fixture frames' if limit else None});offset+=duration
manifest={'duration_s':offset,'presentation':'78-second scenario of measured sensor time; displays saved panels at2-second intervals, not a rendered video','segments':segments,'playlist':playlist,'scope':'TUM real RGB-D with supplied camera pose; synthetic fixture world forecast; JAAD real image-plane forecast. Maps and histories reset between segments. No hardware actuation.','timing_limit':'Replay panels show per-frame pipeline timing captured while other experiments may be active; formal latency results are separate bench runs.'}
assert 60<=offset<=90
(root/'demo/scenario.json').write_text(json.dumps(manifest,indent=2))
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Indoor Perception Lab · evidence replay</title><style>body{margin:0;background:#111923;color:#eff4fa;font:16px system-ui}main{max-width:1200px;margin:auto;padding:20px}h1{font-size:24px;margin:0 0 8px}p{line-height:1.5;color:#b9c8d8}img{display:block;width:100%;border-radius:8px;background:white}nav{display:flex;gap:12px;align-items:center;margin:16px 0}input{flex:1}button{background:#82cfaa;border:0;border-radius:6px;padding:10px 22px;font-weight:700}output{min-width:110px}small{display:block;margin:12px 0;color:#b9c8d8}#sample{font-family:monospace}a{color:#82cfaa}</style><main><h1>Indoor Perception Lab</h1><p>Independent candidate portfolio · measured sensor replay · overall PARTIAL</p><nav><button id="play">Play</button><input id="time" aria-label="Sensor timeline" type="range" min="0" value="0" step="0.1"><output id="clock"></output></nav><small id="sample"></small><img id="frame" alt="Verified sensor output, semantic or geometry mask, map, forecast and status"><p id="scope"></p><small>Saved panels at approximately 2-second intervals. Forecast errors use held-out labels in separate evaluators. Model scores are uncalibrated; unknown map cells remain unknown. Local benchmark timings are separate from these replay overlays.</small><a href="scenario.json">Panel hashes and scenario manifest</a></main><script>const DATA=__DATA__;let active=false,previous=0;const range=document.querySelector('#time'),frame=document.querySelector('#frame'),button=document.querySelector('#play');range.max=DATA.duration_s;document.querySelector('#scope').textContent=DATA.scope;function show(){let t=+range.value,p=DATA.playlist[0];for(const q of DATA.playlist){if(q.time_s<=t)p=q;else break}frame.src=p.file;document.querySelector('#clock').textContent=t.toFixed(1)+' / '+DATA.duration_s.toFixed(1)+' s';document.querySelector('#sample').textContent=p.segment+' · '+p.sample_id}range.oninput=show;button.onclick=()=>{active=!active;previous=0;button.textContent=active?'Pause':'Play'};function step(now){if(active){if(previous){range.value=Math.min(DATA.duration_s,+range.value+(now-previous)/1000);show();if(+range.value>=DATA.duration_s){active=false;button.textContent='Replay';range.value=0}}previous=now}requestAnimationFrame(step)}show();requestAnimationFrame(step);</script></html>'''
(root/'demo/index.html').write_text(html.replace('__DATA__',json.dumps(manifest)))
print(json.dumps({'duration_s':offset,'verified_panel_files':len(playlist),'output':'demo/index.html'}))
